-- PLANECITOS · Nuevos tiempos (45 min y 1 hora) + 40 actividades nuevas
-- Ejecutar en Supabase > SQL Editor, DESPUÉS de 0004_actividades_100.sql

-- 1. Permitir 45 y 60 minutos
alter table public.activities drop constraint if exists activities_duration_check;
alter table public.activities add constraint activities_duration_check check (duration in (5, 15, 30, 45, 60));

-- 2. 40 actividades nuevas
on conflict (slug) do nothing;

-- Revisión: total por duración (debe sumar 140)
select duration, count(*) as total from public.activities group by duration order by duration;
