insert into public.activities
  (slug, title, short_description, description, min_age, max_age, duration, category, location, materials, material_tags, adult_help, preparation, steps, tip, premium)
values
  ('paseo-de-colores', 'Paseo de colores', 'Una caminata buscando cosas rojas, verdes y amarillas.', 'Salgan a caminar por el barrio y busquen cosas de cada color: carros, flores, puertas.', 2, 5, 30, 'aprender', 'afuera', '{}'::text[], array['nada']::text[], true, 'Nada.', array['Escojan un color para empezar.', 'Caminen despacio buscando cosas de ese color.', 'Cada vez que encuentre una, que la señale y diga el color.', 'Cambien de color en cada cuadra.']::text[], 'Para los de 2 años, empieza solo con rojo y amarillo.', true),
  ('tesoros-del-parque', 'Tesoros del parque', 'Una bolsa para guardar hojas, piedras y palitos.', 'En el parque, recojan pequeños tesoros naturales y al llegar a casa los organizan.', 2, 5, 30, 'aprender', 'afuera', array['una bolsa de tela o papel']::text[], array['nada']::text[], true, 'Nada.', array['Lleven una bolsa al parque.', 'Recojan hojas, palitos y piedras grandes.', 'Al llegar, pongan todo en la mesa.', 'Sepárenlos por tipo, color o tamaño.']::text[], 'Revisa que las piedras sean grandes si tu hijo tiene 2 años.', true),
  ('masaje-de-pelota', 'Masaje de pelota', 'Una pelota que rueda despacio por la espalda.', 'Un momento de calma: haz rodar una pelota suave por la espalda de tu hijo mientras le cuentas una historia.', 2, 5, 5, 'tranquilo', 'casa', array['una pelota suave']::text[], array['nada']::text[], true, 'Nada.', array['Que se acueste boca abajo en la cama o el tapete.', 'Rueda la pelota despacio por su espalda.', 'Cuéntale que es un carrito que pasea por una montaña.', 'Cambien: que él te lo haga a ti.']::text[], 'Funciona muy bien antes de dormir o después del baño.', true),
  ('arrullo-de-peluches', 'Arrullo de peluches', 'Cantarle a los peluches para que se duerman.', 'Tu hijo acuesta a sus peluches y les canta una canción suave para dormirlos.', 2, 4, 15, 'tranquilo', 'casa', array['peluches', 'una cobija pequeña']::text[], array['nada']::text[], false, 'Nada.', array['Que escoja tres peluches.', 'Hagan una camita con la cobija.', 'Canten juntos una canción de cuna.', 'Apaguen la luz y digan buenas noches a cada uno.']::text[], 'Es una buena forma de bajar el ritmo antes de su propia siesta.', true),
  ('baile-en-familia', 'Baile en familia', 'Una canción, todos de pie y a bailar.', 'Pongan música y bailen juntos. Cada canción, alguien distinto propone un paso.', 2, 5, 15, 'juntos', 'cualquier', array['música']::text[], array['nada']::text[], false, 'Nada.', array['Pon una canción que les guste.', 'Baila tú primero un paso sencillo.', 'Que todos lo copien.', 'En la siguiente canción, que él invente el paso.']::text[], 'Bailar juntos es de las formas más fáciles de soltar energía.', true),
  ('galletas-en-familia', 'Galletas en familia', 'Mezclar, amasar y cortar galletas con moldes.', 'Preparen galletas sencillas. Los niños ayudan a mezclar, amasar y cortar figuras; tú te encargas del horno.', 2, 5, 60, 'juntos', 'casa', array['harina', 'mantequilla', 'azúcar', 'un huevo', 'moldes o un vaso', 'horno']::text[], array['nada']::text[], true, '10 minutos.', array['Mezclen en un platón 2 tazas de harina, 1/2 taza de azúcar, 100 g de mantequilla y el huevo.', 'Que amase hasta que quede una masa suave.', 'Estiren la masa y corten figuras con moldes o un vaso.', 'Tú las horneas unos 12 minutos; luego las comen juntos.']::text[], 'El horno es solo para adultos. Los de 2 años pueden ayudar a mezclar y a cortar.', true),
  ('banar-a-la-muneca', 'Bañar a la muñeca', 'Agua tibia, una esponja y una muñeca que necesita baño.', 'Tu hijo baña a una muñeca o un muñeco plástico, la seca y la viste.', 2, 4, 15, 'juntos', 'casa', array['un platón con agua tibia', 'una muñeca o muñeco plástico', 'una esponja', 'una toalla']::text[], array['nada']::text[], true, '2 minutos.', array['Pon el platón sobre una toalla.', 'Que meta la muñeca al agua.', 'Que la enjabone y la enjuague.', 'Que la seque y la vista.']::text[], 'Quédate a su lado mientras haya agua.', true),
  ('cajon-de-telas', 'Cajón de telas', 'Telas suaves, ásperas y brillantes para sacar y meter.', 'Llena una caja con pedazos de tela de distintas texturas para que tu hijo explore por su cuenta.', 2, 3, 15, 'solo', 'casa', array['una caja', 'pedazos de tela, pañoletas o bufandas']::text[], array['carton']::text[], false, '2 minutos.', array['Pon en la caja 6 u 8 telas distintas.', 'Deja la caja a su alcance.', 'Que saque, toque y se ponga las telas.', 'Quédate cerca mientras explora.']::text[], 'Evita telas con cordones largos o piezas que se desprendan.', true),
  ('llenar-y-vaciar', 'Llenar y vaciar', 'Vasos, un balde y agua para pasar de un lado a otro.', 'Con vasos y un balde con agua, tu hijo llena, vacía y trasvasa a su ritmo.', 2, 4, 15, 'solo', 'afuera', array['un balde con poca agua', 'vasos y recipientes plásticos']::text[], array['nada']::text[], true, '2 minutos.', array['Pon el balde en el patio o el balcón.', 'Dale vasos de varios tamaños.', 'Que llene y vacíe como quiera.', 'Cuando termine, que riegue una planta con el agua.']::text[], 'Usa poca agua y quédate a su lado todo el tiempo.', true),
  ('grande-y-pequeno', 'Grande y pequeño', 'Ordenar cosas de la casa de la más grande a la más pequeña.', 'Junta objetos parecidos de distintos tamaños y que tu hijo los ordene.', 2, 4, 5, 'aprender', 'casa', array['3 o 4 objetos parecidos de distinto tamaño: cucharas, zapatos, ollas']::text[], array['nada']::text[], false, '1 minuto.', array['Pon los objetos revueltos en el piso.', 'Pregúntale cuál es el más grande.', 'Que los ponga en fila del más grande al más pequeño.', 'Cambien de objetos y repitan.']::text[], 'Usa zapatos de la familia: le encanta reconocer de quién es cada uno.', true),
  ('mision-en-el-parque', 'Misión en el parque', 'Columpio, tobogán y una carrera hasta el árbol.', 'Convierte la visita al parque en una misión con estaciones: cada juego es una prueba.', 2, 5, 45, 'moverse', 'afuera', '{}'::text[], array['nada']::text[], true, 'Nada.', array['Al llegar, anuncia la misión: pasar por todas las estaciones.', 'Estación 1: 10 empujones en el columpio.', 'Estación 2: bajar tres veces por el tobogán.', 'Estación 3: carrera hasta el árbol más grande y de vuelta.']::text[], 'Lleva agua y una merienda para la mitad de la misión.', true),
  ('picnic-en-el-parque', 'Picnic en el parque', 'Una manta, la merienda y una tarde al aire libre.', 'Lleven una manta y la merienda al parque y armen una tarde completa: comer, jugar y descansar.', 2, 5, 60, 'juntos', 'afuera', array['una manta', 'la merienda', 'una pelota']::text[], array['nada']::text[], true, '10 minutos.', array['Preparen juntos la merienda en casa.', 'Busquen un lugar con sombra y extiendan la manta.', 'Coman y luego jueguen con la pelota.', 'Terminen acostados mirando las nubes.']::text[], 'Pregúntenle qué formas ve en las nubes.', true),
  ('titeres-de-dedo', 'Títeres de dedo', 'Personajes de papel para contar un cuento con los dedos.', 'Hagan títeres pequeños de papel para los dedos y cuenten una historia tranquila.', 3, 5, 15, 'tranquilo', 'casa', array['papel', 'colores', 'cinta']::text[], array['papel', 'colores', 'cinta']::text[], true, '2 minutos.', array['Recorta tiras de papel del ancho de un dedo.', 'Que dibuje una cara en cada una.', 'Enróllalas en sus dedos y pégalas con cinta.', 'Cuenten un cuento con los personajes.']::text[], 'Un cuento corto y en voz baja lo prepara para descansar.', true),
  ('pintar-piedras', 'Pintar piedras', 'Piedras lisas que se vuelven mariquitas, caras y peces.', 'Recojan piedras lisas y píntenlas con témpera para decorar la casa o el jardín.', 3, 5, 45, 'crear', 'cualquier', array['piedras lisas', 'témperas', 'pinceles', 'papel periódico']::text[], array['colores']::text[], true, 'Recoger las piedras, 10 minutos.', array['Laven y sequen las piedras.', 'Cubran la mesa con papel periódico.', 'Que pinte cada piedra como quiera.', 'Déjenlas secar y pónganlas en una matera.']::text[], 'Las piedras grandes y planas son más fáciles de pintar.', true),
  ('fortaleza-de-cojines', 'Fortaleza de cojines', 'Todos los cojines de la casa para construir sin ayuda.', 'Tu hijo construye su propia fortaleza con los cojines del sofá y de las camas.', 3, 5, 30, 'solo', 'casa', array['cojines', 'cobijas']::text[], array['nada']::text[], false, 'Nada.', array['Junta todos los cojines en la sala.', 'Dile que construya una fortaleza como quiera.', 'Que le ponga una puerta con una cobija.', 'Que te invite a conocerla cuando esté lista.']::text[], 'Al final, que ayude a devolver cada cojín a su lugar.', true),
  ('album-de-recortes', 'Álbum de recortes', 'Recortar fotos de revistas y pegarlas por temas.', 'Con revistas viejas, tu hijo recorta imágenes y arma un álbum por temas: animales, comida, carros.', 3, 5, 30, 'solo', 'casa', array['revistas viejas', 'tijeras de punta roma', 'papel', 'pegante en barra']::text[], array['papel']::text[], false, 'Nada.', array['Que escoja un tema.', 'Que busque y recorte imágenes de ese tema.', 'Que las pegue en hojas.', 'Unan las hojas para hacer el álbum.']::text[], 'Si recortar le cuesta, que rasgue con los dedos.', true),
  ('regar-las-plantas', 'Regar las plantas', 'Una regadera y la misión de cuidar las matas de la casa.', 'Tu hijo se encarga de regar las plantas y revisar cómo están.', 3, 5, 15, 'aprender', 'cualquier', array['una regadera o un vaso']::text[], array['nada']::text[], false, 'Nada.', array['Muéstrale qué plantas necesitan agua.', 'Que llene la regadera con poca agua.', 'Que riegue cada planta sin encharcarla.', 'Revisen juntos si hay hojas nuevas.']::text[], 'Pueden hacerlo cada semana: es una tarea que le da responsabilidad.', true),
  ('arepitas-en-familia', 'Arepitas en familia', 'Amasar y formar arepas pequeñas para la merienda.', 'Preparen arepas pequeñas. Tu hijo amasa y les da forma; tú las asas.', 3, 5, 45, 'juntos', 'casa', array['harina de maíz precocida', 'agua tibia', 'sal', 'un poco de queso opcional']::text[], array['nada']::text[], true, '5 minutos.', array['Mezclen 1 taza de harina, 1 taza de agua tibia y una pizca de sal.', 'Que amase hasta que la masa no se pegue.', 'Que forme bolitas y las aplaste como arepitas.', 'Tú las asas; cuando estén tibias, se las comen juntos.']::text[], 'La estufa es solo para adultos. Agregar queso a la masa le encanta.', true),
  ('fiesta-de-peluches', 'Fiesta de peluches', 'Decorar, poner música y celebrar con los peluches.', 'Organicen una fiesta para los peluches: decoración, música, merienda y juegos.', 3, 5, 60, 'juntos', 'casa', array['peluches', 'papel', 'colores', 'cinta', 'la merienda']::text[], array['papel', 'colores', 'cinta']::text[], false, '5 minutos.', array['Hagan guirnaldas de papel y péguenlas con cinta.', 'Sienten a los peluches alrededor de la mesa.', 'Sirvan la merienda y pongan música.', 'Jueguen a las estatuas con los peluches de público.']::text[], 'Que escoja de quién es el cumpleaños y le canten.', true),
  ('caza-de-bichos', 'Caza de bichos', 'Buscar hormigas, mariposas y caracoles sin tocarlos.', 'Una caminata para observar insectos y pequeños animales en el parque o el jardín.', 3, 5, 45, 'aprender', 'afuera', array['una lupa opcional', 'papel y colores para dibujar']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Busquen bajo las hojas, en los troncos y en el pasto.', 'Cuando encuentren un bicho, obsérvenlo sin tocarlo.', 'Pregúntale cuántas patas tiene y de qué color es.', 'Al llegar a casa, que dibuje los que vio.']::text[], 'Recuérdale mirar sin tocar: así cuidan a los animales y a sus manos.', true),
  ('pintar-con-musica', 'Pintar con música', 'Pintar al ritmo de una canción lenta y luego de una rápida.', 'Pon música y que tu hijo pinte lo que siente con cada canción.', 3, 5, 30, 'tranquilo', 'casa', array['papel', 'témperas o colores', 'música']::text[], array['papel', 'colores']::text[], false, '2 minutos.', array['Pon una canción lenta y que pinte siguiendo la música.', 'Cambia a una canción rápida.', 'Que note cómo cambian sus trazos.', 'Terminen con una canción suave y comparen los dibujos.']::text[], 'Pregúntale qué color le recuerda cada canción.', true),
  ('lavar-la-bicicleta', 'Lavar la bicicleta', 'Balde, esponja y la bici o el carrito más limpio del barrio.', 'Tu hijo lava su bicicleta, triciclo o carritos de juguete en el patio.', 3, 5, 45, 'juntos', 'afuera', array['un balde con agua y jabón', 'una esponja', 'un trapo', 'la bicicleta o juguetes con ruedas']::text[], array['nada']::text[], true, '5 minutos.', array['Llenen el balde con agua y jabón.', 'Que enjabone la bici con la esponja.', 'Enjuaguen con agua limpia.', 'Que la seque con el trapo.']::text[], 'Ponle ropa vieja: se va a mojar y eso es parte de la diversión.', true),
  ('obra-de-teatro', 'Obra de teatro', 'Ensayar y presentar una obra para la familia.', 'Inventen una obra corta, hagan boletos y preséntenla a la familia.', 4, 5, 60, 'juntos', 'casa', array['disfraces o ropa vieja', 'papel', 'colores', 'una cobija como telón']::text[], array['papel', 'colores']::text[], true, '10 minutos.', array['Inventen una historia corta con tres partes.', 'Escojan disfraces para cada personaje.', 'Hagan boletos de papel e inviten a la familia.', 'Ensayen dos veces y presenten la obra.']::text[], 'Grábenla para verla después todos juntos.', true),
  ('castillo-de-carton', 'Castillo de cartón', 'Cajas grandes que se vuelven torres, puertas y ventanas.', 'Construyan un castillo con cajas de cartón para jugar adentro o con muñecos.', 4, 5, 60, 'crear', 'casa', array['cajas de cartón', 'colores', 'cinta', 'tijeras para el adulto']::text[], array['carton', 'colores', 'cinta']::text[], true, '5 minutos.', array['Junten cajas de varios tamaños.', 'Tú recortas puertas y ventanas.', 'Que pinte las paredes y las torres.', 'Únanlas con cinta y jueguen adentro.']::text[], 'Guárdenlo: el castillo puede crecer con cajas nuevas.', true),
  ('pistas-del-tesoro', 'Pistas del tesoro', 'Cinco pistas escondidas que llevan a un premio.', 'Esconde pistas con dibujos por la casa; cada una lleva a la siguiente hasta el tesoro.', 4, 5, 45, 'juntos', 'casa', array['papel', 'colores', 'un pequeño premio']::text[], array['papel', 'colores']::text[], true, '10 minutos.', array['Dibuja 5 pistas: cada una muestra dónde está la siguiente.', 'Escóndelas por la casa en orden.', 'Dale la primera pista.', 'Que siga las pistas hasta encontrar el tesoro.']::text[], 'El premio puede ser escoger el próximo planecito.', true),
  ('olimpiadas-en-el-parque', 'Olimpiadas en el parque', 'Carreras, saltos y lanzamientos con medallas de papel.', 'Organicen unas olimpiadas en el parque con varias pruebas y medallas hechas en casa.', 4, 5, 60, 'moverse', 'afuera', array['papel', 'colores', 'una pelota']::text[], array['papel', 'colores']::text[], true, '10 minutos para las medallas.', array['En casa, hagan medallas de papel.', 'En el parque, marquen una pista de carreras.', 'Hagan pruebas: correr, saltar lejos y lanzar la pelota.', 'Al final, entreguen las medallas a todos.']::text[], 'Que todos ganen medalla: lo importante es participar.', true),
  ('golosa-con-tiza', 'Golosa con tiza', 'La golosa de siempre, dibujada en el andén o el patio.', 'Dibujen una golosa con tiza en el patio o el andén y jueguen por turnos.', 4, 5, 15, 'moverse', 'afuera', array['tiza', 'una tapa o piedrita']::text[], array['colores']::text[], false, '3 minutos.', array['Dibujen las casillas del 1 al 8 con tiza.', 'Lancen la tapa a la casilla 1.', 'Salten en un pie sin pisar esa casilla.', 'Avancen a la siguiente casilla en cada turno.']::text[], 'La tiza se borra con agua: pueden dejar el andén limpio al final.', true),
  ('rompecabezas-largo', 'Rompecabezas largo', 'Un rompecabezas grande para armar sin afán.', 'Armen juntos un rompecabezas de muchas piezas, con calma y conversando.', 4, 5, 45, 'tranquilo', 'casa', array['un rompecabezas de 24 a 48 piezas']::text[], array['nada']::text[], true, 'Nada.', array['Volteen todas las piezas hacia arriba.', 'Empiecen por los bordes.', 'Separen las piezas por colores.', 'Armen el resto por partes.']::text[], 'Si no lo terminan, déjenlo en una bandeja y sigan mañana.', true),
  ('mi-libro-de-cuentos', 'Mi libro de cuentos', 'Dibujar y armar su propio libro, página por página.', 'Tu hijo inventa un cuento y lo dibuja en hojas que luego se unen como un libro.', 4, 5, 45, 'solo', 'casa', array['4 o 5 hojas', 'colores', 'cinta o grapadora']::text[], array['papel', 'colores', 'cinta']::text[], false, '2 minutos.', array['Dobla las hojas por la mitad.', 'Que dibuje una parte del cuento en cada página.', 'Escribe tú lo que te dicte.', 'Une las hojas por el lomo y que le ponga título.']::text[], 'Léanlo antes de dormir: será su libro favorito.', true),
  ('feria-de-juegos', 'Feria de juegos', 'Estaciones de bolos, lanzamiento y limbo por toda la casa.', 'Monten una feria con varias estaciones de juego y boletos de papel para cada una.', 4, 5, 60, 'moverse', 'casa', array['botellas plásticas', 'medias enrolladas', 'un balde', 'un palo de escoba', 'papel']::text[], array['papel']::text[], true, '10 minutos.', array['Armen tres estaciones: bolos, lanzar al balde y limbo.', 'Hagan boletos de papel.', 'Que pague un boleto por cada estación.', 'Al final, cuenten cuántos puntos hizo.']::text[], 'Inviten a hermanos o primos: con más jugadores es más divertido.', true),
  ('fotografo-por-un-dia', 'Fotógrafo por un día', 'Un celular y una lista de fotos para tomar en el paseo.', 'Dale a tu hijo un celular viejo o el tuyo con supervisión, y una lista de cosas para fotografiar en el paseo.', 4, 5, 45, 'aprender', 'afuera', array['un celular']::text[], array['nada']::text[], true, 'Nada.', array['Antes de salir, hagan una lista: un perro, una flor, algo rojo.', 'Que tome una foto de cada cosa.', 'Revisen juntos las fotos.', 'Escojan su favorita y cuenten por qué.']::text[], 'Mostrarle cómo sostener el celular con dos manos evita caídas.', true),
  ('pizza-casera', 'Pizza casera', 'Cada uno arma su pizza con sus ingredientes favoritos.', 'Usando pan árabe o base lista, cada uno arma su propia pizza y tú la horneas.', 5, 5, 60, 'juntos', 'casa', array['pan árabe o bases de pizza', 'salsa de tomate', 'queso', 'ingredientes al gusto', 'horno']::text[], array['nada']::text[], true, '10 minutos.', array['Pon los ingredientes en platos pequeños.', 'Que unte la salsa sobre su base.', 'Que agregue el queso y sus ingredientes.', 'Tú la horneas y la comen juntos.']::text[], 'El horno es solo para adultos.', true),
  ('laboratorio-de-colores', 'Laboratorio de colores', 'Mezclar agua de colores para descubrir colores nuevos.', 'Con vasos de agua y colorante, tu hijo descubre qué color sale al mezclar.', 5, 5, 30, 'aprender', 'casa', array['vasos transparentes', 'agua', 'colorante de alimentos rojo, azul y amarillo', 'una cuchara']::text[], array['nada']::text[], true, '5 minutos.', array['Llena tres vasos con agua y ponle un color a cada uno.', 'Pregúntale qué pasará si mezcla rojo y azul.', 'Que mezcle un poco en un vaso vacío.', 'Repitan con las otras mezclas y nombren los colores nuevos.']::text[], 'Hazlo sobre una bandeja: el colorante mancha.', true),
  ('barco-que-flota', 'Barco que flota', 'Construir un barco con botellas y probarlo en el agua.', 'Construyan un barco con botellas plásticas y cartón y pruébenlo en la bañera o un platón.', 5, 5, 60, 'crear', 'cualquier', array['2 botellas plásticas', 'cartón', 'cinta', 'un platón grande o la bañera']::text[], array['carton', 'cinta']::text[], true, '5 minutos.', array['Unan dos botellas con cinta.', 'Hagan una vela de cartón y péguenla.', 'Prueben el barco en el agua.', 'Pongan tapas encima para ver cuánto carga.']::text[], 'Quédate a su lado mientras haya agua.', true),
  ('mapa-del-parque', 'Mapa del parque', 'Recorrer el parque y dibujar su mapa.', 'Caminen por el parque y luego dibujen juntos un mapa con los juegos, los árboles y los caminos.', 5, 5, 45, 'aprender', 'afuera', array['papel', 'colores']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Recorran el parque fijándose en lo que hay.', 'Siéntense en una banca con el papel.', 'Que dibuje los juegos, los árboles y los caminos.', 'Marquen con una X su lugar favorito.']::text[], 'La próxima visita, usen el mapa para buscar algo.', true),
  ('torneo-de-juegos-de-mesa', 'Torneo de juegos de mesa', 'Tres juegos, una tabla de puntos y un campeón.', 'Organicen un torneo en familia con juegos de mesa o de cartas que tengan en casa.', 5, 5, 45, 'juntos', 'casa', array['juegos de mesa o cartas', 'papel para los puntos']::text[], array['papel']::text[], false, 'Nada.', array['Escojan tres juegos cortos.', 'Hagan una tabla de puntos en papel.', 'Jueguen cada juego y anoten quién gana.', 'Al final, sumen y entreguen el título de campeón.']::text[], 'Perder también se practica: celebren a todos al final.', true),
  ('la-nube-tranquila', 'La nube tranquila', 'Imaginar que flotan en una nube y respirar despacio.', 'Una relajación guiada: acostados, imaginan que flotan en una nube mientras respiran despacio.', 5, 5, 15, 'tranquilo', 'cualquier', '{}'::text[], array['nada']::text[], true, 'Nada.', array['Acuéstense en un lugar cómodo.', 'Pídele que cierre los ojos y respire despacio.', 'Cuéntale con voz suave que flota en una nube sobre su ciudad.', 'Que te cuente qué vio en su viaje.']::text[], 'Úsala en las noches en que le cuesta dormir.', true),
  ('laberintos-en-papel', 'Laberintos en papel', 'Dibujar laberintos y que otro los resuelva.', 'Tu hijo dibuja laberintos para que tú los resuelvas, y tú le dibujas uno a él.', 5, 5, 30, 'solo', 'casa', array['papel', 'colores']::text[], array['papel', 'colores']::text[], false, 'Nada.', array['Dibújale un laberinto sencillo.', 'Que lo resuelva con un color.', 'Que él dibuje uno para ti.', 'Hagan uno cada vez más difícil.']::text[], 'Empieza con caminos anchos y pocas salidas.', true),
  ('lanzar-y-atrapar', 'Lanzar y atrapar', 'Una pelota y un reto: cada vez un paso más lejos.', 'Practiquen lanzar y atrapar una pelota, alejándose un paso después de cada acierto.', 5, 5, 30, 'moverse', 'afuera', array['una pelota']::text[], array['nada']::text[], false, 'Nada.', array['Párense cerca, a dos pasos.', 'Lancen la pelota suave para atraparla con las dos manos.', 'Si la atrapa, den un paso atrás.', 'Cuenten hasta qué distancia lograron llegar.']::text[], 'Una pelota suave y grande es más fácil al principio.', true),
  ('campamento-en-casa', 'Campamento en casa', 'Carpa de cobijas, linterna, historias y merienda.', 'Una noche de campamento en la sala: construyen la carpa, cenan adentro y cuentan historias.', 5, 5, 60, 'juntos', 'casa', array['cobijas', 'sillas', 'cojines', 'una linterna', 'la merienda']::text[], array['nada']::text[], true, '10 minutos.', array['Construyan la carpa con sillas y cobijas.', 'Llenen el piso de cojines.', 'Coman la merienda adentro con la linterna.', 'Cuenten historias hasta que les dé sueño.']::text[], 'Apaguen todas las luces de la casa para que se sienta como un campamento de verdad.', true)
